#include <bits/stdc++.h>
using namespace std;

template<class F>
struct Modular {
    using T=typename std::decay<decltype((F::get()))>::type;
    T val;
    explicit operator T() const { return val; }
    Modular():val(){}
    template<class U> Modular_(U v):val(T(v%(F::get()))){ if(val<0)val+=(F::get()); }
    [[nodiscard]] bool operator==(Modular b) const { return val == b.val; }
    [[nodiscard]] bool operator!=(Modular b) const { return val != b.val; }
    [[nodiscard]] bool operator<(Modular b) const { return val < b.val; }
    [[nodiscard]] bool operator>(Modular b) const { return val > b.val; }
    [[nodiscard]] bool operator<=(Modular b) const { return val <= b.val; }
    [[nodiscard]] bool operator>=(Modular b) const { return val >= b.val; }
    [[nodiscard]] friend Modular operator-(Modular x) { x.val=x.val?(F::get())-x.val:0; return x; }
    Modular& operator+=(Modular m) { if ((val += m.val) >= (F::get())) val -= (F::get()); return *this; }
    Modular& operator-=(Modular m) { if ((val -= m.val) < 0) val += (F::get()); return *this; }
    Modular& operator*=(Modular m) {
        if(__builtin_constant_p(m.val)){
            switch(m.val){
                case 1: return *this;
                case 2: return *this+=*this;
                case 3: return *this+=*this+*this;
                case 0: return *this=0;
                case -1: return *this=-*this;
            }
        }else if(__builtin_constant_p(val)){
            return *this=m**this;
        }
        if(std::is_same<T, int>::value){
            val = int((int64_t)val*m.val%(F::get()));
        }else if(std::is_same<T, int64_t>::value){
            uint64_t result=
                (uint64_t)val*(uint64_t)m.val-
                uint64_t((long double)val*m.val/(F::get()))*(uint64_t)(F::get());
            result+=(F::get());
            if(result>=(F::get())){
                result-=(F::get());
                if(result>=(F::get())) result-=(F::get());
            }
            val=result;
        }else{
            assert(false);
        }
        return *this;
    }
    template<class U>
    [[nodiscard]] Modular pow(U p) const {
        Modular a=*this;
        Modular ans=1; for (; p; p>>=1, a*=a) if (p&1) ans*=a;
        return ans;
    }
    [[nodiscard]] Modular inv() const {
        T a=val,b=(F::get()), ax=1,bx=0;
        while(b){
            T q=a/b, t=a%b;
            a=b; b=t;
            t=ax-bx*q; ax=bx; bx=t;
        }
        assert(a==1);
        if(ax<0)ax+=(F::get());
        return ax;
    }
    Modular& operator/=(Modular m) { return (*this) *= m.inv(); }
    friend Modular operator+(Modular a, Modular b) { return a += b; }
    friend Modular operator-(Modular a, Modular b) { return a -= b; }
    friend Modular operator*(Modular a, Modular b) { return a *= b; }
    friend Modular operator/(Modular a, Modular b) { return a /= b; }
};

template<class T, T x> struct TGetter{ static T get(){ return x; } };
template<int MOD> using Modular=Modular_<TGetter<int, MOD>>;

using mod_type=Modular<1000000007>;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin >> n;
    vector<mod_type> prob(n*n);
    for(auto& v: prob){
        int p; cin >> p;
        v=mod_type(1)/100*p;
    }
    vector<mod_type> total;
    int mid=n/2;
    array<int, 64> mask_vals;
    int count_mask=0;
    for(int mask=0; mask<(1<<6); ++mask){
        mask_vals[mask]=__builtin_popcount(mask)==mid ? count_mask++ : -1;
    }
    total.resize(1<<count_mask);
    auto process=[&](int l, int r, auto handle){
        int len=r-l;
        for(int edge_mask=0; edge_mask<(1<<(len*n)); ++edge_mask){
            mod_type total_prob=1;
            for(int tmp=edge_mask, i=l*n; i<r*n; ++i, tmp>>=1){
                total_prob*=tmp&1 ? prob[i] : 1 - prob[i];
                if(total_prob==0) goto skip_edge;
            }
            std::array<char, 3> data{};
            int match_sets=0;
            while(true){
                int match_mask=0;
                for(int i=0; i<len; ++i){
                    if(!((edge_mask>>(i*n+data[i]))&1)) goto skip_match;
                    if(match_mask&(1<<data[i])) goto skip_match;
                    match_mask|=1<<data[i];
                }
                if(r==n) match_mask^=(1<<n)-1;
                match_sets|=1<<mask_vals[match_mask];
            skip_match:
                for(int i=len-1; i>=0; --i){
                    if(data[i]==n-1){ data[i]=0; --i; }
                    else{ ++data[i]; break; }
                }
            }
        skip_edge:
            handle(match_sets, total_prob);
        }
    };
    process(0, mid, [&](int s, mod_type p){ total[s]+=p; });
    for(int i=1; i<(int)total.size(); i<<=1)
        for(int j=0; j<(int)total.size(); ++j)
            if(!(j&i))
                total[j|i]+=total[j];
    mod_type res=0;
    process(mid, n, [&](int s, mod_type p){
        res+=p*(total.back()-total[total.size()-1-s]);
    });
    cout<<(int)res<<'\n';
    return 0;
}
